"use client";

import "./checkbox.css";
import { Checkbox as BaseCheckbox } from "@base-ui/react/checkbox";
import { Check } from "lucide-react";
import type React from "react";
import { cn } from "@/lib/cn";

import { CheckboxContext, useCheckboxContext } from "./checkbox.context";
import { checkboxVariants, type CheckboxVariants } from "./checkbox.variants";

export type CheckboxProps = CheckboxVariants & React.ComponentProps<typeof BaseCheckbox.Root>;

export const CheckboxRoot = ({ children, className, size, variant, ...props }: CheckboxProps) => {
  const slots = checkboxVariants({ size, variant });

  return (
    <CheckboxContext.Provider value={{ slots }}>
      <BaseCheckbox.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseCheckbox.Root>
    </CheckboxContext.Provider>
  );
};

export type CheckboxIndicatorProps = React.ComponentProps<typeof BaseCheckbox.Indicator>;

export const CheckboxIndicator = ({ children, className, ...props }: CheckboxIndicatorProps) => {
  const { slots } = useCheckboxContext();
  return (
    <BaseCheckbox.Indicator className={cn(slots.indicator(), className)} {...props}>
      {children ?? <Check />}
    </BaseCheckbox.Indicator>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const checkboxVariants = tv({
  slots: {
    root: "checkbox",
    indicator: "checkbox__indicator",
  },
  variants: {
    size: {
      sm: {
        root: "checkbox--sm",
        indicator: "checkbox__indicator--sm",
      },
      md: {
        root: "checkbox--md",
        indicator: "checkbox__indicator--md",
      },
      lg: {
        root: "checkbox--lg",
        indicator: "checkbox__indicator--lg",
      },
    },
    variant: {
      default: {
        root: "checkbox--default",
      },
      outline: {
        root: "checkbox--outline",
      },
    },
  },
  defaultVariants: {
    size: "md",
    variant: "default",
  },
});

export type CheckboxVariants = VariantProps<typeof checkboxVariants>;

"use client";

import { createContext, useContext } from "react";

import { checkboxVariants } from "./checkbox.variants";

export type CheckboxContext = {
  slots: ReturnType<typeof checkboxVariants>;
};

export const CheckboxContext = createContext<CheckboxContext | null>(null);

export const useCheckboxContext = () => {
  const context = useContext(CheckboxContext);
  return context ?? { slots: checkboxVariants() };
};

.checkbox {
  @apply border-input bg-background text-primary-foreground focus-visible:outline-ring data-checked:bg-primary data-checked:border-primary data-indeterminate:bg-primary data-indeterminate:border-primary inline-flex shrink-0 items-center justify-center rounded-sm border p-0 shadow-xs transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.checkbox--sm {
  @apply h-4 w-4;
}

.checkbox--md {
  @apply h-5 w-5;
}

.checkbox--lg {
  @apply h-6 w-6;
}

.checkbox__indicator {
  @apply flex items-center justify-center text-current data-unchecked:hidden;
}

.checkbox__indicator svg {
  @apply h-full w-full stroke-[3];
}

.checkbox__indicator--sm {
  @apply h-3 w-3;
}

.checkbox__indicator--md {
  @apply h-3.5 w-3.5;
}

.checkbox__indicator--lg {
  @apply h-4 w-4;
}

import { CheckboxIndicator, CheckboxRoot } from "./checkbox";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/checkbox/content.md
 */
export const Checkbox = {
  Indicator: CheckboxIndicator,
  Root: CheckboxRoot,
};

export { CheckboxIndicator, CheckboxRoot };

export type { CheckboxIndicatorProps, CheckboxProps } from "./checkbox";
export { CheckboxContext, useCheckboxContext } from "./checkbox.context";
export { type CheckboxVariants, checkboxVariants } from "./checkbox.variants";
